package com.sumedha.commerce.product.mapper; import com.sumedha.commerce.product.dto.response.*; import com.sumedha.commerce.product.entity.Product; import com.sumedha.commerce.product.entity.ProductImage; import com.sumedha.commerce.product.entity.ProductAttribute; import java.util.*; public final class ProductMapper {private ProductMapper(){} public static ProductSummaryResponse toSummary(Product p){return new ProductSummaryResponse(p.getId(),p.getSku(),p.getName(),p.getSlug(),p.getPrice(),p.getCurrency());} public static ProductResponse toResponse(Product p,CategoryResponse c,BrandResponse b,List<ProductImageResponse> i,List<ProductAttributeResponse> a){return new ProductResponse(p.getId(),p.getSku(),p.getName(),p.getSlug(),p.getShortDescription(),p.getDescription(),c,b,p.getPrice(),p.getCurrency(),p.getStatus(),p.isActive(),i,a,p.getCreatedAt(),p.getUpdatedAt());} public static ProductImageResponse toImageResponse(ProductImage i){return new ProductImageResponse(i.getId(),i.getUrl(),i.getAltText(),i.getSortOrder(),i.isPrimaryImage());} public static ProductAttributeResponse toAttributeResponse(ProductAttribute a){return new ProductAttributeResponse(a.getId(),a.getName(),a.getValue());}}
